contract InvMutTest is Test {
    C c;
    function setUp() public {
        c = new C();
    }
    function testFuzz_property(uint256 _value, bytes calldata _data) public {
        vm.assume(_value < address(c).balance);
        address target = address(new Target());
        vm.deal(address(target), 0);
        uint256 targetBalBefore = target.balance;
        vm.deal(address(c), _value + 1);
        vm.prank(c.owner());
        c.sendMoney(target, _value, _data);
        uint256 targetBalAfter = target.balance;
        assertTrue(targetBalAfter - targetBalBefore == _value);
    }
}

contract Target {
    fallback() external payable {}
    receive() external payable {}
}

