pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint256 _value) public {
        // bind _value to a reasonable range, keeping it wide, but prevent overflow and ensure contract has funds
        bound(_value, 0, 1000 ether);
        vm.assume(_value <= address(c).balance); // only test when contract has enough balance

        // record balance before
        uint256 balanceBefore = address(c).balance;

        // prank as owner and call sendMoney; target is a fresh EOA with no code, low-level call always succeeds
        address target = makeAddr("target");
        vm.prank(c.owner());
        c.sendMoney(target, _value, "");

        // the reference contract must reduce its own balance by exactly _value
        assertTrue(address(c).balance == balanceBefore - _value);
    }
}

