pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint112 value, address target, bytes calldata data) public {
        // ensure target has no code (EOA) so call returns true and balance is measurable
        vm.assume(target.code.length == 0);
        vm.assume(target != address(c));
        // record target balance before
        uint256 balBefore = target.balance;
        // owner calls sendMoney
        vm.prank(c.owner());
        (bool ok,) = address(c).call{value: value}(abi.encodeWithSignature("sendMoney(address,uint256,bytes)", target, value, data));
        require(ok, "sendMoney failed");
        uint256 balAfter = target.balance;
        assertTrue(balAfter == balBefore + value);
    }
}

