pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint256 amount, address target, bytes calldata data) public {
        // Bound to a reasonable range and ensure target is not the contract itself
        vm.assume(amount > 0 && amount <= address(c).balance + 100 ether);
        vm.assume(target != address(c) && target != address(0));
        // Fund the contract so it can send
        vm.deal(address(c), amount + 1 ether);
        // Record balance before
        uint256 beforeBal = address(c).balance;
        // Owner calls sendMoney
        vm.prank(c.owner());
        c.sendMoney(target, amount, data);
        // After the call, the contract's balance should be exactly beforeBal - amount
        // (assuming the low-level call succeeds, which it always does for an EOA)
        uint256 afterBal = address(c).balance;
        assertTrue(afterBal == beforeBal - amount);
    }
}

