pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint256 amount, address payable target) public {
        // Keep amount admissible: nonzero, not exceeding contract balance, and contract must be fundable.
        vm.assume(amount > 0);
        vm.deal(address(c), amount * 2);
        vm.deal(c.owner(), amount);
        uint256 balBefore = address(c).balance;
        vm.prank(c.owner());
        (bool ok,) = target.call{value: 0}("");
        vm.assume(ok); // target must accept a 0-value call (so it exists and doesn't revert on call)
        vm.prank(c.owner());
        (bool success, ) = address(c).call(abi.encodeWithSignature("sendMoney(address,uint256,bytes)", target, amount, ""));
        vm.assume(success); // sendMoney must not revert (property is about balance change on success)
        uint256 balAfter = address(c).balance;
        assertTrue(balBefore - balAfter == amount);
    }
}
